  function initCanvas(){const canvas=$('#map-canvas');
if(!canvas)return;
const c=currentCampaign(),t=tabletopFor(c),ctx=canvas.getContext('2d');
let bgImage=null,measureStart=null,measureEnd=null,measurePointer=null;
const asset=state.assets.find(a=>a.id===t.mapAssetId);
if(asset?.type?.startsWith('image/')){bgImage=new Image();
bgImage.onload=draw;
bgImage.src=asset.data;
}let w=0,h=0;
function resize(){const rect=canvas.getBoundingClientRect(),dpr=Math.min(devicePixelRatio||1,2);
w=rect.width;
h=rect.height;
canvas.width=Math.max(1,w*dpr);
canvas.height=Math.max(1,h*dpr);
ctx.setTransform(dpr,0,0,dpr,0,0);
draw();
}
function draw(){if(!w||!h)return;
ctx.clearRect(0,0,w,h);
ctx.fillStyle='#25231d';
ctx.fillRect(0,0,w,h);
if(bgImage?.complete&&bgImage.naturalWidth){const scale=Math.max(w/bgImage.naturalWidth,h/bgImage.naturalHeight)*t.zoom;
const iw=bgImage.naturalWidth*scale,ih=bgImage.naturalHeight*scale;
ctx.drawImage(bgImage,(w-iw)/2+t.panX,(h-ih)/2+t.panY,iw,ih);
}else{ctx.fillStyle='#302c22';
for(let i=0;
i<30;
i++){const x=((i*137)%Math.max(w,1)),y=((i*83)%Math.max(h,1));
ctx.globalAlpha=.12;
ctx.beginPath();
ctx.arc(x,y,(i%4)+1,0,Math.PI*2);
ctx.fill();
}ctx.globalAlpha=1;
}

