   function parseRoll(expression){const m=String(expression).trim().toLowerCase().match(/^(\d*)d(\d+)(?:\s*([+-])\s*(\d+))?$/);if(!m)throw new Error('Use uma fórmula como d20, 2d6+3 ou 1d100.');const count=Number(m[1]||1),sides=Number(m[2]),mod=Number(m[4]||0)*(m[3]==='-'?-1:1);if(count<1||count>100||sides<2||sides>10000||mod>100000||mod< -100000)throw new Error('Limites: até 100 dados, d2–d10000 e modificador de 100000.');const dice=Array.from({length:count},()=>1+Math.floor(Math.random()*sides));return{expression:String(expression).trim(),dice,mod,total:dice.reduce((a,b)=>a+b,0)+mod};}
